CREATE TABLE IF NOT EXISTS documents(document_id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,filename TEXT NOT NULL,mime_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS document_chunks(chunk_id TEXT PRIMARY KEY,document_id TEXT NOT NULL,page_number INTEGER,sequence INTEGER NOT NULL,text_hash TEXT NOT NULL,extractor_version TEXT NOT NULL,source_offset_start INTEGER,source_offset_end INTEGER,FOREIGN KEY(document_id) REFERENCES documents(document_id));